typedef unsigned long long big_int;

struct string_buf {
  big_int* data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

  inline int compare(const string_buf& buf) const {
    int i;
    const char* a = reinterpret_cast<const char*>(data);
    const char* b = reinterpret_cast<const char*>(buf.data);
    int cmp_len = (char_length < buf.char_length ? char_length : buf.char_length);
    for (i = 0; i < cmp_len; i++) {
      if (a[i] == b[i]) continue;
      if (b[i] > a[i]) return 1;
      if (b[i] < a[i]) return -1;
    }
    if (buf.char_length > char_length) return 1;
    if (buf.char_length < char_length) return -1;
    return 0;
  }
};

struct stringx {
  char* chars;
  string_buf* my_buf;
};

inline bool operator<(const stringx& lhs, const stringx& rhs) {
  return (lhs.my_buf->compare(*rhs.my_buf) == 1);
}

struct ref_t {
  stringx label;
  void* ptr;
  unsigned int count;
};

struct less_by_label {
  inline bool operator()(const ref_t* a, const ref_t* b) const {
    return (a->label < b->label);
  }
};

struct node {
  int color;
  node* parent;
  node* left;
  node* right;
  ref_t* value;
};

struct iterator {
  node* _M_node;
  iterator(node* x) : _M_node(x) {}
};

struct tree {
  node* _M_header;
  less_by_label _M_key_compare;

  node*& _M_root() const { return _M_header->parent; }
  static node*& _M_left(node* x) { return x->left; }
  static node*& _M_right(node* x) { return x->right; }
  static ref_t* const& _S_key(node* x) { return x->value; }

  iterator find(ref_t* const& k) const;
};

