iterator tree::find(ref_t* const& k) const {
  node* y = _M_header;
  node* x = _M_root();
  while (x != 0)
    if (!_M_key_compare(_S_key(x), k))
      y = x, x = _M_left(x);
    else
      x = _M_right(x);
  return iterator(y == _M_header || _M_key_compare(k, _S_key(y)) ?
